JS = ("const sleep=ms=>new Promise(r=>setTimeout(r,ms));"
      "const setv=(el,v)=>{const p=el.tagName==='TEXTAREA'?HTMLTextAreaElement.prototype:HTMLInputElement.prototype;"
      "Object.getOwnPropertyDescriptor(p,'value').set.call(el,v);el.dispatchEvent(new Event('input',{bubbles:true}));};"
      "const sets=(el,v)=>{Object.getOwnPropertyDescriptor(HTMLSelectElement.prototype,'value').set.call(el,v);el.dispatchEvent(new Event('change',{bubbles:true}));};"
      "const btn=t=>[...document.querySelectorAll('button')].find(b=>b.textContent.replace(/\\s+/g,'').includes(t));"
      "const q=s=>document.querySelector(s);")
CLEAR = JS + "if(btn('クリア')){btn('クリア').click();await sleep(400);}"
TAB = lambda name: JS + "[...document.querySelectorAll('.tabs [role=tab]')].find(b=>b.textContent.trim()==='%s').click();await sleep(500);" % name
# 一覧：キーワードで1行にしてから行の「無効にする」「有効に戻す」を押す（見本の商品の状態を変える）
FIND = lambda kw: CLEAR + "setv(q('.es-search input[placeholder^=\"品番\"]'),'%s');q('.es-search__actions button[type=submit]').click();await sleep(500);" % kw
# 新規・編集：入力欄に値を入れる
SETV = lambda label, v: "setv(q('[aria-label=\"%s\"]'),'%s');await sleep(150);" % (label, v)
# CSV取込のステップ2：CSV出力と同じ列のデータ（API）から、1行目の商品名を変えた更新の見本と、品番が誤りの行を足してファイルとして入れる
CSVUP = JS + ("const res=await fetch('/api/domain/csv/export',{method:'POST',credentials:'include',headers:{'Content-Type':'application/json','x-es-site':'ops'},body:JSON.stringify({args:{entity:'products',scope:{site:'ops'}}})});"
    "const t=await res.json();const esc=v=>'\"'+String(v??'').replace(/\"/g,'\"\"')+'\"';const rows=[t.head,...t.rows];"
    "const ni=t.head.findIndex(h=>h.startsWith('商品名【'));const ji=t.head.findIndex(h=>h.startsWith('JANコード'));const r0=t.rows[0];if(ni>=0)r0[ni]=r0[ni]+' 改';const nw=t.rows[1].slice();nw[0]='新規1';if(ni>=0)nw[ni]='新規の見本商品';if(ji>=0)nw[ji]='';rows.push(nw);"
    "const bad=t.rows[0].slice();bad[0]='XX999999';rows.push(bad);"
    "const text='\\ufeff'+rows.map(r=>r.map(esc).join(',')).join('\\r\\n');const inp=q('input[type=file]');const dt=new DataTransfer();dt.items.add(new File([text],'取込テスト.csv',{type:'text/csv'}));inp.files=dt.files;inp.dispatchEvent(new Event('change',{bubbles:true}));await sleep(2500);")
# CSV取込：見出しの列が違うファイル（ファイル全体のエラー）
CSVBAD = JS + ("const text='\\ufeff品番,知らない列\\r\\nM001,あ\\r\\n';const inp=q('input[type=file]');const dt=new DataTransfer();dt.items.add(new File([text],'列が違う.csv',{type:'text/csv'}));inp.files=dt.files;inp.dispatchEvent(new Event('change',{bubbles:true}));await sleep(1500);")

